/**
 * LocalSecretStore — the local-default SecretStore (ISC-54).
 *
 * Per-user secrets (the PocketSmith X-Developer-Key, the auth PIN) are held in
 * a single AES-256-GCM encrypted file. The key never appears as plaintext at
 * rest (ISC-56): the file content is ciphertext, and a value is never logged or
 * returned in an error message.
 *
 * The master key is read from PENNY_LOCAL_SECRET_KEY (base64, 32 bytes). If
 * unset, a random key is generated once and persisted next to the vault file;
 * this is the local trust boundary, equivalent to an OS keychain entry. In a
 * hardened local deploy this would be the OS keychain / PAI secret store.
 *
 * On-disk shape (decrypted): { "<userId>": { "<secretName>": "<value>" } }.
 */

import type { UserId } from "../auth.ts";
import type { SecretStore, SecretName } from "../secrets.ts";
import {
  aesGcmDecrypt,
  aesGcmEncrypt,
  b64ToBytes,
  bytesToB64,
  bytesToUtf8,
  randomBytes,
  utf8ToBytes,
} from "./crypto.ts";

type Vault = Record<string, Partial<Record<SecretName, string>>>;

const HOME = process.env.HOME ?? ".";
const DEFAULT_VAULT_PATH = `${HOME}/.penny/secrets.enc`;
const DEFAULT_KEY_PATH = `${HOME}/.penny/secret.key`;

export class LocalSecretStore implements SecretStore {
  private readonly vaultPath: string;
  private readonly keyPath: string;
  private keyBytes: Uint8Array | null = null;

  constructor(vaultPath: string = DEFAULT_VAULT_PATH, keyPath: string = DEFAULT_KEY_PATH) {
    this.vaultPath = vaultPath;
    this.keyPath = keyPath;
  }

  async get(userId: UserId, name: SecretName): Promise<string | null> {
    const vault = await this.read();
    return vault[userId]?.[name] ?? null;
  }

  async set(userId: UserId, name: SecretName, value: string): Promise<void> {
    const vault = await this.read();
    const forUser = vault[userId] ?? {};
    forUser[name] = value;
    vault[userId] = forUser;
    await this.write(vault);
  }

  async delete(userId: UserId, name: SecretName): Promise<void> {
    const vault = await this.read();
    const forUser = vault[userId];
    if (!forUser) return;
    delete forUser[name];
    await this.write(vault);
  }

  private async masterKey(): Promise<Uint8Array> {
    if (this.keyBytes) return this.keyBytes;
    const fromEnv = process.env.PENNY_LOCAL_SECRET_KEY;
    if (fromEnv) {
      this.keyBytes = b64ToBytes(fromEnv);
      return this.keyBytes;
    }
    const keyFile = Bun.file(this.keyPath);
    if (await keyFile.exists()) {
      this.keyBytes = b64ToBytes((await keyFile.text()).trim());
      return this.keyBytes;
    }
    const fresh = randomBytes(32);
    await Bun.write(this.keyPath, bytesToB64(fresh));
    this.keyBytes = fresh;
    return fresh;
  }

  private async read(): Promise<Vault> {
    const file = Bun.file(this.vaultPath);
    if (!(await file.exists())) return {};
    const packed = (await file.text()).trim();
    if (!packed) return {};
    const key = await this.masterKey();
    const plaintext = bytesToUtf8(await aesGcmDecrypt(key, packed));
    return JSON.parse(plaintext) as Vault;
  }

  private async write(vault: Vault): Promise<void> {
    const key = await this.masterKey();
    const packed = await aesGcmEncrypt(key, utf8ToBytes(JSON.stringify(vault)));
    await Bun.write(this.vaultPath, packed);
  }
}

