14	 *   PENNY_PERIOD          YYYY-MM to render (default current month)
15	 *   PENNY_NAB_ACCOUNT_ID  NAB account id for the Holding-vs-NAB tile
16	 *   PENNY_HOLDING_MATCH   name fragment for the Holding envelope (default "holding")
17	 *   PENNY_PULSE_PATH      override the widget output path
18	 *
19	 * This module does NOT read the deployment-mode env var; the composition root
20	 * resolves it and exposes the resolved mode on container.config.deployMode.
21	 */
22	
23	import { buildContainer } from "../src/composition.ts";
24	import { installEgressGuard } from "../src/security/egress.ts";
