=== zerobased logic ===
/**
 * The zero-based check and income variance (ISC-30, ISC-31, ISC-32, ISC-65).
 *
 * The ISA's final resolution (Changelog, 2026-06-26): zero-based applies to the
 * PLAN, not to actual cash. The check compares total spending allocations to
 * total BUDGETED income and raises an alert on any imbalance. It NEVER blocks a
 * save or a view (ISC-32 anti). Income variance is a separate, first-class idea:
 * each income envelope carries budgeted vs actual, and the difference is the
 * surplus/deficit on that envelope (ISC-31, ISC-65).
 *
 * Pure functions. No I/O.
 */

import type { IncomeEnvelope } from "../domain/types.ts";

export interface ZeroBasedState {
  readonly budgetedIncomeCents: number;
  readonly allocatedCents: number;
  /** budgetedIncome - allocated. Positive = unallocated, negative = over-allocated. */
  readonly unallocatedCents: number;
  /** True on any imbalance. An alert, never a block (ISC-30). */
  readonly zeroBasedAlert: boolean;
}

/**
 * Compare total budgeted income to total spending allocations (ISC-30).
 * `allocationsByEnv` is the period's direct allocation per spending envelope.
 */
export function zeroBasedCheck(
  incomeEnvelopes: readonly IncomeEnvelope[],
  allocationsByEnv: ReadonlyMap<string, number>,
): ZeroBasedState {
  const budgetedIncomeCents = incomeEnvelopes.reduce((s, i) => s + i.budgetedCents, 0);
  let allocatedCents = 0;
  for (const v of allocationsByEnv.values()) allocatedCents += v;
  const unallocatedCents = budgetedIncomeCents - allocatedCents;
  return {
    budgetedIncomeCents,
    allocatedCents,
    unallocatedCents,
    zeroBasedAlert: unallocatedCents !== 0,
  };
}

export interface IncomeVariance {
  readonly incomeEnvelopeId: string;
  readonly name: string;
  readonly budgetedCents: number;
  readonly actualCents: number;
