/**
 * Create a many-to-one effective-dated mapping (ISC-19). Closes any open prior
 * mapping for the same category so history stays effective-dated, then reports
 * how many transactions now resolve to the new envelope.
 */
async mapCategory(userId: UserId, req: MapCategoryRequest): Promise<MapCategoryResponse> {
  const existing = await this.store.listMappings(userId);
  for (const m of existing) {
    if (m.categoryId === req.categoryId && m.effectiveTo === null) {
      await this.store.upsertMapping(userId, { ...m, effectiveTo: req.effectiveFrom });
    }
  }
  const mapping: CategoryMapping = {
    id: uuid(),
    userId,
    categoryId: req.categoryId,
    envelopeId: req.envelopeId,
    effectiveFrom: req.effectiveFrom,
    effectiveTo: null,
  };
  await this.store.upsertMapping(userId, mapping);

  const txs = await this.store.listTransactions(userId);
  const remappedCount = txs.filter(
    (t) => t.categoryId === req.categoryId && t.date >= req.effectiveFrom,
  ).length;

  await this.event(userId, "mapping.create", { mapping, remappedCount });
  return { mappingId: mapping.id, remappedCount };
}

/** Holding-vs-NAB drift for a period: the named euphoric invariant (ISC-21, ISC-43). */
async holdingBalance(userId: UserId, asOf?: string): Promise<number> {
  const [txs, mappings] = await Promise.all([
    this.store.listTransactions(userId),
    this.store.listMappings(userId),
  ]);
  const activity = computeActivity(txs, mappings, this.config, asOf !== undefined ? { asOf } : {});
  return activity.holdingCents;
}

