1	import * as React from "react";
2	import { useNavigate } from "react-router-dom";
3	import { ArrowLeft, Save, CheckCircle2, AlertTriangle, Wallet } from "lucide-react";
4	import type { GridResponse, EditBudgetLine } from "@contract";
5	import type { ChangeScope } from "@domain";
6	import { call, isApiError } from "@/lib/api";
7	import { cn, formatCents } from "@/lib/utils";
8	import { Button } from "@/components/ui/button";
9	import { Input } from "@/components/ui/input";
10	import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";
11	
12	/**
13	 * Edit Budget wizard (ISC-72). The recurring template is edited here, not inline
14	 * on the grid. Every line is an editable allocation; the running zero-based check
15	 * compares total allocations to budgeted income and alerts (never blocks) when
16	 * unbalanced (ISC-30 / ISC-32). Scope decides whether the change updates the
17	 * recurring template (ongoing) or just this month (ISC-67). Data is the real grid
18	 * response with explicit loading and empty states; nothing is invented (ISC-83).
19	 */
20	export function EditBudgetPage() {
21	  const navigate = useNavigate();
22	  const [grid, setGrid] = React.useState<GridResponse | null>(null);
23	  const [loading, setLoading] = React.useState(true);
24	  const [draft, setDraft] = React.useState<Record<string, number>>({});
25	  const [scope, setScope] = React.useState<ChangeScope>("ongoing");
26	  const [saved, setSaved] = React.useState(false);
27	  const [busy, setBusy] = React.useState(false);
28	  const [error, setError] = React.useState<string | null>(null);
29	
30	  React.useEffect(() => {
31	    void (async () => {
32	      try {
33	        const res = await call("GET /api/envelopes");
34	        setGrid(res);
35	        setDraft(Object.fromEntries(res.rows.map((r) => [r.id, r.allocationCents])));
36	      } catch (e) {
37	        setError(e instanceof Error ? e.message : "Could not load the budget.");
38	      } finally {
39	        setLoading(false);
40	      }
41	    })();
42	  }, []);
43	
44	  const rows = grid?.rows ?? [];
45	
46	  // Only leaf envelopes (and childless parents) take a direct allocation; a
47	  // parent with children rolls up, so we edit children. Inbox is not budgeted.
48	  const editable = rows.filter((r) => r.id !== "env-inbox" && !rows.some((c) => c.parentId === r.id));
49	
50	  const totalAllocated = editable.reduce((s, r) => s + (draft[r.id] ?? r.allocationCents), 0);
51	  const totalIncome = grid?.budgetedIncomeCents ?? 0;
52	  const remaining = totalIncome - totalAllocated;
53	  const balanced = remaining === 0;
