import * as React from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, Save, CheckCircle2, AlertTriangle, Wallet } from "lucide-react";
import type { GridResponse, EditBudgetLine } from "@contract";
import type { ChangeScope } from "@domain";
import { call, isApiError } from "@/lib/api";
import { cn, formatCents } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";

/**
 * Edit Budget wizard (ISC-72). The recurring template is edited here, not inline
 * on the grid. Every line is an editable allocation; the running zero-based check
 * compares total allocations to budgeted income and alerts (never blocks) when
 * unbalanced (ISC-30 / ISC-32). Scope decides whether the change updates the
 * recurring template (ongoing) or just this month (ISC-67). Data is the real grid
 * response with explicit loading and empty states; nothing is invented (ISC-83).
 */
export function EditBudgetPage() {
  const navigate = useNavigate();
  const [grid, setGrid] = React.useState<GridResponse | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [draft, setDraft] = React.useState<Record<string, number>>({});
  const [scope, setScope] = React.useState<ChangeScope>("ongoing");
  const [saved, setSaved] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    void (async () => {
      try {
        const res = await call("GET /api/envelopes");
        setGrid(res);
        setDraft(Object.fromEntries(res.rows.map((r) => [r.id, r.allocationCents])));
      } catch (e) {
        setError(e instanceof Error ? e.message : "Could not load the budget.");
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const rows = grid?.rows ?? [];

  // Only leaf envelopes (and childless parents) take a direct allocation; a
  // parent with children rolls up, so we edit children. Inbox is not budgeted.
  const editable = rows.filter((r) => r.id !== "env-inbox" && !rows.some((c) => c.parentId === r.id));

  const totalAllocated = editable.reduce((s, r) => s + (draft[r.id] ?? r.allocationCents), 0);
  const totalIncome = grid?.budgetedIncomeCents ?? 0;
  const remaining = totalIncome - totalAllocated;
  const balanced = remaining === 0;

  const setCents = (id: string, dollars: string) =>
    setDraft((prev) => ({ ...prev, [id]: Math.round((parseFloat(dollars) || 0) * 100) }));

  const onSave = async () => {
    setBusy(true);
    setError(null);
    const lines: EditBudgetLine[] = editable.map((r) => ({
      envelopeId: r.id,
      amountCents: draft[r.id] ?? r.allocationCents,
    }));
    try {
      const res = await call("POST /api/budget/edit", { lines, scope });
      if (isApiError(res)) {
        setError(res.error);
        return;
      }
      setSaved(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Could not save the budget.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="mx-auto max-w-3xl space-y-5">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <Button asChild variant="ghost" size="icon">
            <button onClick={() => navigate(-1)} aria-label="Back">
              <ArrowLeft className="h-5 w-5" />
            </button>
          </Button>
          <div>
            <h1 className="text-xl font-semibold tracking-tight md:text-2xl">Edit budget</h1>
            <p className="text-sm text-muted-foreground">Edit the recurring template. It auto-rolls into each month.</p>
          </div>
        </div>
        <div className="w-40">
          <Select value={scope} onValueChange={(v) => setScope(v as ChangeScope)}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ongoing">Every month</SelectItem>
              <SelectItem value="this_month">This month only</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {loading ? (
        <div className="py-16 text-center text-sm text-muted-foreground animate-pulse">Loading budget…</div>
      ) : editable.length === 0 ? (
        <div className="rounded-lg border border-dashed bg-card px-6 py-12 text-center">
          <Wallet className="mx-auto mb-3 h-8 w-8 text-muted-foreground" />
          <p className="text-sm font-medium">No budget set up yet</p>
          <p className="mt-1 text-sm text-muted-foreground">Add envelopes from the budget screen to edit their allocations.</p>
        </div>
      ) : (
        <>
          {/* Running zero-based check (alert, not block) */}
          <div
            className={cn(
              "flex items-center justify-between gap-3 rounded-lg border px-4 py-3 text-sm",
              balanced ? "border-success/40 bg-success/10 text-success" : "border-warning/40 bg-warning/10 text-warning"
            )}
          >
            <div className="flex items-center gap-2 font-medium">
              {balanced ? <CheckCircle2 className="h-5 w-5" /> : <AlertTriangle className="h-5 w-5" />}
              {balanced
                ? "Every dollar allocated."
                : remaining > 0
                  ? `${formatCents(remaining)} left to allocate.`
                  : `Over budget by ${formatCents(Math.abs(remaining))}.`}
            </div>
            <div className="tnum text-xs">
              Income {formatCents(totalIncome)} · Allocated {formatCents(totalAllocated)}
            </div>
          </div>

          <div className="rounded-lg border bg-card divide-y divide-border/40">
            {editable.map((r) => (
              <div key={r.id} className="flex items-center justify-between gap-3 px-4 py-2.5">
                <span className="truncate text-sm font-medium">{r.name}</span>
                <div className="flex items-center gap-1">
                  <span className="text-sm text-muted-foreground">$</span>
                  <Input
                    type="number"
                    min="0"
                    step="0.01"
                    inputMode="decimal"
                    className="h-9 w-28 text-right tnum"
                    value={((draft[r.id] ?? r.allocationCents) / 100).toFixed(2)}
                    onChange={(e) => setCents(r.id, e.target.value)}
                  />
                </div>
              </div>
            ))}
          </div>

          <div className="flex items-center justify-between">
            {error ? (
              <span className="text-sm text-destructive">{error}</span>
            ) : saved ? (
              <span className="flex items-center gap-1 text-sm text-success">
                <CheckCircle2 className="h-4 w-4" /> Saved. Recorded to budget history.
              </span>
            ) : (
              <span className="text-xs text-muted-foreground">
                Saving never blocks on an unbalanced budget; it only raises the alert.
              </span>
            )}
            <Button onClick={onSave} disabled={busy}>
              <Save className="h-4 w-4" /> {busy ? "Saving…" : "Save budget"}
            </Button>
          </div>
        </>
      )}
    </div>
  );
}

