export function normalise(amountCents: number, period: BudgetPeriod): NormalisedAmounts {
  const weekly = toWeekly(amountCents, period);
  const monthly = (weekly * WEEKS_PER_YEAR) / MONTHS_PER_YEAR;
  const annual = monthly * MONTHS_PER_YEAR;
  const fortnightly = weekly * 2;
  return {
    weeklyCents: Math.round(weekly),
    fortnightlyCents: Math.round(fortnightly),
    monthlyCents: Math.round(monthly),
    annualCents: Math.round(annual),
  };
}

/**
 * The monthly equivalent of an amount entered in any period (ISC-94). This is
 * the figure the capital and zero-base maths use. A monthly input returns itself
 * unchanged.
 */
export function monthlyEquivalentCents(amountCents: number, period: BudgetPeriod): number {
  return normalise(amountCents, period).monthlyCents;
}

