export type BudgetPeriod = "weekly" | "fortnightly" | "monthly" | "annual";

// Re-declared note: EnvelopeType gains "envelope" (variable-with-targets, the
// spreadsheet Full Budget discretionary lines). income, expense, saving and
// envelope are the four budget-page sections; expense/saving/envelope behave
