);
const insTmpl = db.prepare(`INSERT INTO budget_template (user_id,id,envelope_id,amount_cents,period) VALUES (?,?,?,?, 'monthly')`);
const insAlloc = db.prepare(`INSERT INTO allocations (user_id,id,envelope_id,period,amount_cents,scope) VALUES (?,?,?,?,?, 'ongoing')`);
const insMap = db.prepare(`INSERT INTO mappings (user_id,id,category_id,envelope_id,effective_from,effective_to) VALUES (?,?,?,?, '1970-01-01', NULL)`);

const nameToEnv = new Map<string, string>(); // lower envelope name -> id
function makeEnv(id: string, name: string, parentId: string | null, group: string, type: "expense" | "saving" | "envelope", active: boolean, monthlyCents: number | null) {
  insEnv.run(USER, id, parentId, name, group, type, active ? 1 : 0);
  nameToEnv.set(name.toLowerCase(), id);
  if (monthlyCents && monthlyCents > 0) {
    insTmpl.run(USER, `bt-${id}`, id, monthlyCents);
    if (active) insAlloc.run(USER, `al-${id}`, id, PERIOD, monthlyCents);
  }
}

const build = db.transaction(() => {
  // Inbox + category parents.
  insEnv.run(USER, "inbox", null, "Inbox", "", "expense", 1);
  const parents = [...new Set(src.fixedExpenses.map((e) => e.category).filter(Boolean) as string[])];
  for (const p of parents) makeEnv(`cat-${slug(p)}`, p, null, "", "expense", true, null);
  // Fixed expenses under their category parent.
  for (const e of src.fixedExpenses) {
    const pid = e.category ? `cat-${slug(e.category)}` : null;
    makeEnv(`env-${slug(e.name)}`, e.name, pid, e.category ?? "", "expense", e.active, e.monthlyCents);
  }
  // Discretionary expenses, top-level.
  for (const e of src.discretionaryExpenses) makeEnv(`env-${slug(e.name)}`, e.name, null, "", "expense", true, e.monthlyCents);
  // Income envelopes: all of the target flows to expense capital so the zero-base balances.
  for (const i of src.income) insInc.run(USER, `inc-${slug(i.name)}`, i.name, i.name, i.targetCents, i.targetCents, i.targetCents);
});
build();

// Opening carryover from the rollover baseline doc (matched by name), so the
// fold starts at the current month rather than folding three years of history.
const updCarry = db.prepare("UPDATE envelopes SET carryover_cents=?, rollover_start=? WHERE user_id=? AND lower(name)=lower(?)");
const rdoc = await Bun.file(`${import.meta.dir}/../docs/pocketsmith-rollover-baseline.md`).text();
const monthMap: Record<string, string> = { Jan: "01", Feb: "02", Mar: "03", Apr: "04", May: "05", Jun: "06", Jul: "07", Aug: "08", Sep: "09", Oct: "10", Nov: "11", Dec: "12" };
let carrySet = 0;
const applyCarry = db.transaction(() => {
  for (const line of rdoc.split("\n")) {
    const m = line.match(/^\|\s*([^|]+?)\s*\|\s*[^|]*\|\s*([^|]*?)\s*\|\s*[^|]*\|\s*([^|]+?)\s*\|/);
    if (!m) continue;
    const name = m[1]!.trim();
    if (name === "Category" || /no current budget/i.test(m[3]!)) continue;
    const bal = parseFloat(m[3]!.replace(/[$,]/g, ""));
    if (Number.isNaN(bal)) continue;
    const dm = m[2]!.match(/([A-Z][a-z]{2})\s+(\d+),\s+(\d{4})/);
    const iso = dm ? `${dm[3]}-${monthMap[dm[1]!]}-${String(dm[2]).padStart(2, "0")}` : null;
    if (updCarry.run(Math.round(bal * 100), iso, USER, name).changes > 0) carrySet++;
  }
});
applyCarry();
console.log(`[seed] carryover applied from baseline: ${carrySet} envelopes`);

// Alias map: PocketSmith category names that differ from the spreadsheet envelope
// names, including Recreation's granular children which roll up to Recreation.
const ALIAS: Record<string, string> = {
  "health insurance": "Teacher Health", "car registration": "Car Rego",
  "mcc": "MCC Membership", "smlsc": "SMLSC Membership", "uslsc": "USLSC Membership",
  "social": "Recreation", "coffee": "Recreation", "takeaway lunches": "Recreation",
  "takeaway dinners": "Recreation", "takeaway snacks": "Recreation", "takeaway breakfast": "Recreation",
  "rideshare": "Recreation", "adhoc parking": "Recreation", "lottery": "Recreation",
  "life saving": "Recreation", "dating": "Recreation", "dry cleaning": "Recreation",
  "bottleshop": "Recreation", "golf": "Recreation", "fitness extras": "Recreation", "fines": "Recreation",
};
// Income category -> income envelope (for actual income tracking).
const INCOME_ALIAS: Record<string, string> = { "salary": "Income", "surplus income": "Income", "rental income": "Rental" };

let mapped = 0, skippedOld = 0, unmatched = 0;
const incomeCatByEnv = new Map<string, string[]>();
const mapTx = db.transaction(() => {
  for (const c of flatCats) {
    if (c.top === "Old") { skippedOld++; continue; }
    const lc = c.title.toLowerCase();
    const incName = INCOME_ALIAS[lc];
    if (incName) {
      const incId = `inc-${slug(incName)}`;
      (incomeCatByEnv.get(incId) ?? incomeCatByEnv.set(incId, []).get(incId)!).push(c.id);
      continue;
    }
    const envId = nameToEnv.get(lc) ?? (ALIAS[lc] ? nameToEnv.get(ALIAS[lc].toLowerCase()) : undefined);
    if (envId) { insMap.run(USER, `map-${c.id}`, c.id, envId); mapped++; }
    else unmatched++;
  }
});
mapTx();

// Income actuals: current-month sum of each income envelope's mapped categories.
const updIncActual = db.prepare("UPDATE income_envelopes SET actual_cents=? WHERE user_id=? AND id=?");
let incActualSet = 0;
for (const [incId, catIds] of incomeCatByEnv) {
  const ph = catIds.map(() => "?").join(",");
  const row = db.query(
    `SELECT COALESCE(SUM(amount_cents),0) s FROM transactions WHERE user_id=? AND txn_date LIKE ? AND category_id IN (${ph})`,
  ).get(USER, `${PERIOD}%`, ...catIds) as { s: number };
  updIncActual.run(row.s, USER, incId);
  incActualSet++;
}
console.log(`[seed] income actuals set (current month ${PERIOD}): ${incActualSet} envelopes`);

// Resolve how many loaded transactions now hit a real envelope.
const mappedCatIds = new Set(db.query("SELECT category_id FROM mappings WHERE user_id=?").all(USER).map((r: any) => r.category_id));
const txTotal = (db.query("SELECT COUNT(*) n FROM transactions WHERE user_id=?").get(USER) as any).n;
const txResolved = db.query("SELECT COUNT(*) n FROM transactions WHERE user_id=? AND category_id IN (SELECT category_id FROM mappings WHERE user_id=?)").get(USER, USER) as any;

const incTarget = src.income.reduce((s, i) => s + i.targetCents, 0);
const expMonthly = src.fixedExpenses.filter((e) => e.active).reduce((s, e) => s + (e.monthlyCents ?? 0), 0) + src.discretionaryExpenses.reduce((s, e) => s + e.monthlyCents, 0);

console.log(`[seed] envelopes: ${parentsCount()} parents + ${src.fixedExpenses.length} fixed + ${src.discretionaryExpenses.length} discretionary + Inbox`);
console.log(`[seed] income: ${src.income.length} | mappings: ${mapped} (skipped Old categories: ${skippedOld}, unmatched: ${unmatched})`);
console.log(`[seed] transactions resolving to an envelope: ${txResolved.n}/${txTotal}`);
console.log(`[seed] ZERO-BASE: capital $${(incTarget / 100).toFixed(2)} vs budgeted out $${(expMonthly / 100).toFixed(2)} -> residual $${((incTarget - expMonthly) / 100).toFixed(2)}`);
function parentsCount() { return new Set(src.fixedExpenses.map((e) => e.category).filter(Boolean)).size; }
db.close();

/**
 * Shared domain types for Penny. These are the conceptual primitives the
 * business modules reason about. They are deliberately separate from the
 * persistence row shapes in src/platform/store.ts: the store layer is how
 * these are written and read, not what they mean.
 *
 * INVARIANT: all money is integer cents. There are no floats anywhere in the
 * domain. A positive amount is money available/in; a negative amount is a
 * deficit/outflow. Enforces the ISA principle "every dollar is conserved".
 */

import type { UserId } from "../platform/auth.ts";

/** Integer cents. Branded for clarity at call sites; structurally a number. */
export type Cents = number;

/** A calendar month period, e.g. { year: 2026, month: 6 }. The unit of budgeting. */
export interface Period {
  readonly year: number;
  /** 1-12. */
  readonly month: number;
}

/**
 * Rollover behaviour at period end. The domain vocabulary:
 *   roll_carry     - default. Surplus and deficit both carry to next period as
 *                    the envelope's explicit starting carryover (ISC-25).
 *   drain_to_zero  - use-it-or-lose-it. Surplus dropped at period end (ISC-26).
 *   annual_reset   - carries within the year, resets in January (ISC-26).
 */
export type RolloverRule = "roll_carry" | "drain_to_zero" | "annual_reset";

/** What an envelope is aiming at. Annual is shown as target/12 for the MVP (ISC-27). */
export type TargetType = "monthly" | "annual" | "sinking" | "no_target";

/**
 * The three envelope types (ISC-91). A saving envelope behaves identically to an
 * expense envelope (it draws from the pooled expense capital); the distinction is
 * a label/grouping only. Income envelopes are first-class and provide capital.
 */
export type EnvelopeType = "income" | "expense" | "saving";

/**
 * The period a budget line is entered in (ISC-94). Every line normalises to a
 * monthly equivalent for the capital and zero-based maths (see src/budget/normalise.ts).
 */
export type BudgetPeriod = "weekly" | "fortnightly" | "monthly" | "annual";

/**
 * The user-facing primitive. Envelopes form a tree via parentId; a parent is
 * itself spendable and allocatable, and its figures roll up children plus any
 * direct parent activity (ISC-73, ISC-74).
 */
export interface Envelope {
  readonly id: string;
  readonly userId: UserId;
  readonly parentId: string | null;
  readonly name: string;
  /** Legacy flat grouping label; subsumed by the tree (top-level envelopes act as groups). */
  readonly group: string;
  readonly rolloverRule: RolloverRule;
  readonly targetType: TargetType;
  readonly targetAmountCents: Cents;
  /**
   * The envelope type (ISC-91). Additive: a store row defaults to "expense" and
   * an existing DB column backfills to 'expense', so legacy callers that omit it
   * read back as an expense envelope.
   */
  readonly type?: EnvelopeType;
  /** Active flag (ISC-100). Inactive envelopes are excluded from the budget total. Defaults true. */
  readonly active?: boolean;
}

/**
 * A first-class income envelope, one per income source (ISC-65). Budgeted is the
 * expected income; actual is what landed; the variance (actual - budgeted) is the
 * surplus/deficit carried on the envelope (ISC-31).
 *
 * Income works as capital (ISC-92): targetCents is the income target, and
 * capitalToExpenseCents is the portion of that target routed into the shared
 * expense-capital pool that expense/saving envelopes draw from (ISC-93).
 */
export interface IncomeEnvelope {
  readonly id: string;
  readonly userId: UserId;
  readonly name: string;
  readonly source: string;
  readonly budgetedCents: Cents;
  readonly actualCents: Cents;
  /** Income target (ISC-92). Additive; defaults 0. */
  readonly targetCents?: Cents;
  /** Portion of the target routed to the shared expense-capital pool (ISC-92). Additive; defaults 0. */
  readonly capitalToExpenseCents?: Cents;
}

/** The four rolled-up figures rendered on every envelope grid row (ISC-70). */
export interface EnvelopeRollup {
  readonly envelopeId: string;
  /** Starting carryover from the prior period (may be negative). */
  readonly carryoverCents: Cents;
  /** This period's allocation. */
  readonly allocationCents: Cents;
  /** carryover + allocation. */
  readonly totalCents: Cents;
  /** total - spent. */
  readonly leftCents: Cents;
}

/**
 * A transaction sourced from PocketSmith. The raw payload is retained verbatim
 * for diffing on re-sync (ISC-12). amountCents is signed: negative = outflow.
 */
export interface Transaction {
  readonly id: string;
  readonly userId: UserId;
  /** ISO date (YYYY-MM-DD) the swipe happened; envelopes decrement on this date (ISC-24). */
  readonly date: string;
  readonly amountCents: Cents;
  readonly accountId: string;
  readonly categoryId: string | null;
  readonly envelopeId: string | null;
  readonly payee: string;
  readonly isTransfer: boolean;
  readonly isPending: boolean;
  /** Verbatim PocketSmith JSON for diffing (ISC-12). */
  readonly rawJson: string;
}

/**
 * Many categories map to one envelope, effective-dated (ISC-19). A mapping is
 * live for transactions dated on/after effectiveFrom and before effectiveTo.
 */
export interface CategoryMapping {
  readonly id: string;
  readonly userId: UserId;
  readonly categoryId: string;
  readonly envelopeId: string;
  /** ISO date the mapping takes effect. */
  readonly effectiveFrom: string;
  /** ISO date the mapping stops applying, or null for open-ended. */
  readonly effectiveTo: string | null;
}

/**
 * One line of the recurring budget template (ISC-29). The template auto-rolls
 * into each new month with no manual ritual (ISC-76).
 */
export interface BudgetTemplate {
  readonly id: string;
  readonly userId: UserId;
  readonly envelopeId: string;
  readonly amountCents: Cents;
  /**
   * The period the amount is entered in (ISC-94). The monthly equivalent for the
   * zero-base maths is derived via src/budget/normalise.ts. Additive; defaults
   * "monthly", which keeps amountCents its own monthly figure.
   */
  readonly period?: BudgetPeriod;
}

/** Whether a budget change applies only to the current period or to the template (ISC-67). */
export type ChangeScope = "this_month" | "ongoing";

/** Who made a change. Mirrors the ledger actor vocabulary. */
export type Actor = "sync" | "ui" | "agent";

/**
 * An immutable record of a budget-template change, with before/after values,
 * scope, and actor, viewable as a budget history (ISC-77).
 */
export interface BudgetChange {
  readonly id: string;
  readonly userId: UserId;
  readonly ts: number;
  readonly envelopeId: string;
  readonly beforeCents: Cents;
  readonly afterCents: Cents;
  readonly scope: ChangeScope;
  readonly actor: Actor;
}

/**
 * The append-only audit record. The event log is the source of truth: future
 * questions ("why did this envelope go negative on this day?") resolve here
 * (ISC-15). Carries ts, actor, and correlationId.
 */
export interface LedgerEvent {
  readonly id: string;
  readonly userId: UserId;
  readonly ts: number;
  readonly actor: Actor;
  readonly correlationId: string;
  readonly kind: string;
  readonly payloadJson: string;
}

/**
 * A traceable money movement between two envelopes (ISC-89, ISC-90). Records the
 * source, destination, conserved amount, timestamp, actor, correlation id and
 * scope, so every free rebalance is auditable in the movements history.
 */
export interface MoneyMovement {
  readonly id: string;
  readonly userId: UserId;
  readonly ts: number;
  readonly fromEnvelopeId: string;
  readonly toEnvelopeId: string;
  /** Always positive: the conserved amount leaving source and entering destination. */
  readonly amountCents: Cents;
  readonly scope: ChangeScope;
  readonly actor: Actor;
  readonly correlationId: string;
}

/** One end-of-day balance row per envelope per day, powering time-travel (ISC-16, ISC-36). */
export interface Snapshot {
  readonly userId: UserId;
  readonly envelopeId: string;
  /** ISO date (end-of-day T). */
  readonly date: string;
  readonly balanceCents: Cents;
}

